ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
"consecutivo": (payload.result.value.Prefijo default "") ++ (payload.result.value.Secuencia as String default "")
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: "/dynamicQuery",
	body: { 
		"query" :{
 			findAndModify: "MDM_CD_CONSECUTIVO",
 			query: { Serie: "SecuenciaOrden"
  			},
  		update: { "\$inc": { Secuencia: 1 } },
  		new: true
		}
	},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}

%dw 2.0
output application/json
import * from dw::core::Strings

fun ajustarConsecutivo(valor: String) = do {
    var partes = valor splitBy "-"
    // Normalizamos el número final por si viene en notación científica
    var numero = ((partes[-1] default "") as Number as String {format: "0"})
    var prefijoPartes = partes[0 to -2]
    ---
    if (isEmpty(prefijoPartes))
        leftPad(numero, 9, "0")
    else
        (prefijoPartes joinBy "-") ++ "-" ++ leftPad(numero, 9, "0")
}

---
ajustarConsecutivo((vars.consecutivoOrden.consecutivo default "") as String)

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
