set-variable.value:
#[%dw 2.0
output application/java
---
sum(
    payload.result map ((item) ->
        sizeOf(item.bundle.primarios default []) + sum(
            item.bundle.primarios map ((primario) -> sizeOf(primario.secundarios default []))
        )
    )
)]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: "/dynamicQuery",
	body: { 
		"query" :{
 			findAndModify: "MDM_CD_CONSECUTIVO",
 			query: { Serie: "SecuenciaIdServicio"
  			},
  		update: { "\$inc": { Secuencia: vars.totalSR } },
  		new: true
		}
	},
	headers: {
	"client_secret" : p('mongo-db-sapi.security.client-secret'),
	"client_id" : p('mongo-db-sapi.security.client-id'),
	"name": vars.headers.name,
	"X-CORRELATION-ID": vars.headers."X-CORRELATION-ID",
	"source": vars.headers.source,
	"systemId": vars.headers.systemId
},
	queryParameters:{

	},
	uriParameters:{

	}
}

%dw 2.0
output application/json
var totalProductos = vars.totalSR
var consecutivoStr = payload.consecutivo 

var partesConsecutivo = consecutivoStr splitBy "-"
var prefijoConsecutivo = partesConsecutivo[0] ++ "-"
var consecutivoInicial = partesConsecutivo[1] as Number


var listaConsecutivos = (0 to (totalProductos - 1)) map ((i) -> consecutivoInicial - i)


var productosFlatten = flatten(
    vars.bundle.primarios default [] map ((primario) ->
        [{ idProducto: primario."_id"."\$oid", tipo: "PRIMARIO" }]
        ++ (primario.secundarios default [] map ((secundario) ->
                { idProducto: secundario."_id"."\$oid", tipo: "SECUNDARIO" }
           ))
    )
)

var productosConConsecutivo = productosFlatten map ((producto, index) ->
    producto ++ { consecutivo: prefijoConsecutivo ++ ((listaConsecutivos[index]) as String) }
)
---
{
    primarios: productosConConsecutivo
                    filter ($.tipo == "PRIMARIO")
                    map ((p) -> { idProducto: p.idProducto, consecutivo: p.consecutivo }),
    secundarios: productosConConsecutivo
                    filter ($.tipo == "SECUNDARIO")
                    map ((s) -> { idProducto: s.idProducto, consecutivo: s.consecutivo })
}
